it.each(["selection","binding","contract","control","canonical-provider","product","region","thread","parent","control-shape","adapter-thread"] as const)("keeps restart closed for corrupted native %s metadata without changing the original Run",async drift=>{
 const f=await fixture(),run=await f.create("corrupt-restart");await f.start(run);await f.service.stop();const db=new DispatcherDatabase(join(f.root,"data","dispatcher.sqlite"));
 if(drift==="selection")db.handle.prepare("UPDATE entities SET document_json=json_set(document_json,'$.executionSelection.contextFingerprint',?) WHERE kind='run' AND id=?").run("changed",run.id);
 if(drift==="binding")db.handle.prepare("UPDATE entities SET document_json=json_set(document_json,'$.nativeBinding.nativeSessionId',?) WHERE kind='adapter-session' AND id=?").run("other",run.sessionId);
 if(drift==="contract")db.saveEntity("run-contract",run.id,{version:1,revision:1,workspace:{repositoryId:"repo",baseCommit:"other"}});
 if(drift==="control"){const store=new InteractionStore(db),control=store.control(run.sessionId)!;db.handle.prepare("UPDATE session_controls SET document_json=? WHERE session_id=?").run(JSON.stringify({...control,activeRunId:"other"}),run.sessionId);}
 if(drift==="adapter-thread")db.handle.prepare("UPDATE entities SET document_json=json_set(document_json,'$.nativeBinding.nativeThreadId',?) WHERE kind='adapter-session' AND id=?").run("foreign-thread",run.sessionId);
 if(drift==="canonical-provider")db.handle.prepare("UPDATE entities SET document_json=json_set(document_json,'$.providerId',?) WHERE kind='session' AND id=?").run("pi",run.sessionId);
 if(["product","region","thread","parent"].includes(drift)){
  const field=drift==="thread"?"nativeThreadId":drift==="parent"?"parentSessionId":drift,value=drift==="product"?"pi":drift==="region"?"other-region":"other-thread";
  const binding=new InteractionStore(db).binding(run.sessionId)!;const changed={...binding,[field]:value};db.handle.prepare("UPDATE native_bindings SET document_json=? WHERE session_id=?").run(JSON.stringify(changed),run.sessionId);
  for(const kind of ["session","adapter-session"]){const row=db.getEntity(kind,run.sessionId)!;db.handle.prepare("UPDATE entities SET document_json=? WHERE kind=? AND id=?").run(JSON.stringify({...row as object,nativeBinding:changed}),kind,run.sessionId);}
 }
 if(drift==="control-shape"){const control=new InteractionStore(db).control(run.sessionId)!;db.handle.prepare("UPDATE session_controls SET document_json=? WHERE session_id=?").run(JSON.stringify({...control,epoch:"corrupt"}),run.sessionId);}
 const before=db.getEntity("run",run.id);db.close();expect(()=>new ControllerService({dataDirectory:join(f.root,"data"),ownerToken:"fixture-owner",withRunner:true,codexAppServerFactory:f.factory})).toThrow(expect.objectContaining({code:"NATIVE_CONTROL_RUNTIME_UNAVAILABLE"}));const checked=new DispatcherDatabase(join(f.root,"data","dispatcher.sqlite"));try{expect(checked.getEntity("run",run.id)).toEqual(before);expect(f.factory).toHaveBeenCalledOnce();}finally{checked.close();}
});
